SELECT inv.inv_date_sk, inv.inv_warehouse_sk, it.i_item_id, it.i_product_name, inv.inv_quantity_on_hand, it.i_current_price, it.i_wholesale_cost, (inv.inv_quantity_on_hand * it.i_current_price) AS inventory_value, (it.i_current_price - it.i_wholesale_cost) AS margin, CASE WHEN inv.inv_quantity_on_hand > 551 THEN 'High' ELSE 'Low' END AS quantity_level, CASE WHEN it.i_current_price < 4.00 THEN 'Cheap' WHEN it.i_current_price < 2.61 THEN 'Affordable' ELSE 'Expensive' END AS price_category, (inv.inv_quantity_on_hand - 797) AS quantity_minus_threshold FROM inventory inv JOIN item it ON inv.inv_item_sk = it.i_item_sk WHERE inv.inv_date_sk = 2450941
